from lxml import etree

def match_pubdate(node: Any, pubdate_xpaths: List[str]) -> Optional[str]:
    """
    For the given node, returns the first match in the pubdate_xpaths list.

    :param node: An XML/HTML node to search within
    :param pubdate_xpaths: A list of XPath expressions to find the publication date
    :return: The first matched publication date string or None if no match is found
    """
    # Check if the node is valid
    if not isinstance(node, (etree._Element, str)):
        raise ValueError("Node must be an instance of etree._Element or a string representing HTML/XML content")

    # Convert string to Element if necessary
    if isinstance(node, str):
        try:
            node = etree.HTML(node) if '<html>' in node else etree.fromstring(node)
        except etree.XMLSyntaxError as e:
            raise ValueError(f"Invalid XML/HTML content: {e}")

    # Iterate over each XPath expression to find the publication date
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0].strip() if isinstance(matches[0], str) else str(matches[0])
        except etree.XPathEvalError as e:
            raise ValueError(f"Invalid XPath expression: {xpath} - {e}")

    # No match found
    return None

