from typing import List, Dict

def _dictsum(dicts: List[Dict[str, int]]) -> Dict[str, int]:
    """
    Given a list of dictionaries, returns a new dictionary where the values of keys that appear in more than one dictionary are summed up.

    Args:
        dicts (List[Dict[str, int]]): A list of dictionaries containing string keys and integer values.

    Returns:
        Dict[str, int]: A dictionary with summed values for keys that appear in more than one dictionary.
    """
    # Initialize a dictionary to keep track of the sum of values for each key
    result = {}

    # Iterate over each dictionary in the list
    for d in dicts:
        # Iterate over each key-value pair in the current dictionary
        for key, value in d.items():
            # If the key is already in the result dictionary, add the value to the existing sum
            if key in result:
                result[key] += value
            else:
                # Otherwise, initialize the key with the current value
                result[key] = value

    # Filter out keys that only appeared once by checking their presence in all dictionaries
    filtered_result = {key: value for key, value in result.items() if sum(key in d for d in dicts) > 1}

    return filtered_result

