def _replace_register(flow_params: dict | list, register_number: int, register_value: int) -> None:
    """
    Replace the value of flow_params[register_number] with flow_params[register_value] and delete flow_params[register_value].

    :param flow_params: Dictionary or list containing the registers.
    :param register_number: Integer representing the key/index to be replaced.
    :param register_value: Integer representing the key/index whose value will replace the target.
    """
    if register_number == register_value:
        raise ValueError("register_number and register_value cannot be the same.")

    if isinstance(flow_params, dict):
        if register_number in flow_params and register_value in flow_params:
            flow_params[register_number] = flow_params[register_value]
            del flow_params[register_value]
        else:
            raise KeyError('One or both of the provided keys do not exist in the flow_params.')
    elif isinstance(flow_params, list):
        if 0 <= register_number < len(flow_params) and 0 <= register_value < len(flow_params):
            flow_params[register_number] = flow_params[register_value]
            del flow_params[register_value]
        else:
            raise IndexError('One or both of the provided indices are out of range.')

